export function newState(boat=GENERIC_BOAT){const s=JSON.parse(JSON.stringify(DEFAULTS));s.fixedControls={};s.boat=structuredClone(boat);s.sailDesigns=defaultSailDesigns(s.boat);s.sailAreas={gennaker:boat.areas.gennaker,spinnaker:boat.areas.spinnaker};if(boat.id!==GENERIC_BOAT.id)s.genoaSize=105;return s;}
export function courseName(twa){const a=Math.abs(twa);return a<30?'Prua al vento':a<48?'Bolina stretta':a<70?'Bolina larga':a<105?'Traverso':a<145?'Lasco':a<170?'Gran lasco':'Poppa';}
const references=new Map();
export function installReference(reference){references.set(reference.key,reference);if(references.size>32)references.delete(references.keys().next().value);}
export function getReference(s){return references.get(referenceKey(s));}
export function evaluate(s,speed=0,quality='normal'){const m=aeroForces(s,speed,quality),polarTarget=polarSpeed(s.windSpeed,s.windAngle,s),reference=getReference(s);let targetSpeed=0,efficiency=0;if(polarTarget>.01){if(reference&&reference.score>.01){targetSpeed=polarTarget*Math.pow(clamp(m.usefulDrive/reference.score,0,3),1/3);efficiency=100*m.usefulDrive/reference.score;}else{const approximate=.5*1.225*(m.aws*.514444)**2*m.area*Math.max(.08,1.15*Math.sin(Math.abs(m.awa)*RAD)-.12*Math.cos(Math.abs(m.awa)*RAD));targetSpeed=polarTarget*Math.sqrt(clamp(m.usefulDrive/Math.max(1,approximate)));efficiency=100*clamp(m.usefulDrive/Math.max(1,approximate));}}return{...m,polarTarget,targetSpeed,polarEfficiency:polarTarget>.01?speed/polarTarget*100:0,efficiency:clamp(efficiency,0,100),referenceReady:!!reference,referenceScore:reference?.score||0,referenceAttachment:reference?.attachment||0,referencePressure:reference?.maxPressure||0,referenceCp95:reference?.cp95||0};}
export function optimize(s){const reference=computeReference(s);installReference(reference);const result=optimizeForReference(s,reference);Object.assign(s,result.state);return s;}
export function equilibrium(input){const s={...input};delete s.jibAngleRad;delete s.jibAngularVelocity;delete s.jibSide;let v=polarSpeed(s.windSpeed,s.windAngle,s)*.8;for(let i=0;i<24;i++)v=lerp(v,evaluate(s,v).targetSpeed,.45);return evaluate(s,v);}
export {samplePressure};
